    import pandas as pd
    v = pd.read_csv(OUT, keep_default_na=False)
    u = v.drop_duplicates(["intervention", "pubmed_id"])
    chk = u[u.record_ok != "unverifiable"]
    print(len(v), "rows;", len(u), "findings;", len(chk), "checked against an abstract")
    print(chk.record_ok.value_counts().to_dict(), "| relevant:", chk.relevant.value_counts().to_dict())
    rel = chk[chk.relevant == "yes"]
    print("design among relevant:", rel.design_class.value_counts().to_dict(), "| effect:", rel.verified_effect.value_counts().to_dict())
